import pytest

from bedrock_protocol import v1001, v2168

COMMON = {
    "id": 2,
    "synched_properties": v2168.PropertySyncData(
        int_entries=[v2168.PropertySyncData.PropertySyncIntEntry(property_index=1, data=-2)],
        float_entries=[v2168.PropertySyncData.PropertySyncFloatEntry(property_index=2, data=0.5)],
    ),
    "tick": 100,
}

# generated by gophertunnel 6353c49:
# packet.SetActorData{EntityRuntimeID: 2, EntityMetadata: protocol.EntityMetadata{38: float32(0.5)},
#   EntityProperties: protocol.EntityProperties{
#     IntegerProperties: []protocol.IntegerEntityProperty{{Index: 1, Value: -2}},
#     FloatProperties: []protocol.FloatEntityProperty{{Index: 2, Value: 0.5}}},
#   Tick: 100}
V1001 = bytes.fromhex("020126030000003f01010301020000003f64")

# generated by gophertunnel b8bd735:
# packet.SetActorData{EntityRuntimeID: 2, EntityMetadata: protocol.EntityMetadata{38: float32(0.5)},
#   EntityProperties: protocol.EntityProperties{
#     IntegerProperties: []protocol.IntegerEntityProperty{{Index: 1, Value: -2}},
#     FloatProperties: []protocol.FloatEntityProperty{{Index: 2, Value: 0.5}}},
#   Tick: 100}
V2168 = bytes.fromhex("02012603030000003f01010301020000003f64")

GOLDENS = [
    pytest.param(
        v1001.SetActorDataPacket(
            **COMMON,
            packed_items=v1001.SynchedActorData.CopyableDataList(
                data=[v1001.DataItemEntry(id=38, payload=v1001.DataItemFloatPayload(value=0.5))]
            ),
        ),
        V1001,
        id="v1001",
    ),
    pytest.param(
        v2168.SetActorDataPacket(
            **COMMON,
            packed_items=v2168.SynchedActorData.CopyableDataList(
                data=[v2168.DataItemEntry(id=38, payload=v2168.DataItemFloatPayload(value=0.5))]
            ),
        ),
        V2168,
        id="v2168",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_actor_data_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_actor_data_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_2168_adds_one_type_byte_per_data_item():
    assert V2168[:4] + V2168[5:] == V1001
    assert V2168[4:5] == bytes.fromhex("03")


def test_a_1001_body_is_rejected_at_2168():
    with pytest.raises(ValueError, match="at byte"):
        v2168.SetActorDataPacket.from_bytes(V1001)


def test_a_2168_body_is_rejected_at_1001():
    with pytest.raises(ValueError, match="at byte"):
        v1001.SetActorDataPacket.from_bytes(V2168)


def test_an_empty_data_list_encodes_identically_at_1001_and_2168():
    assert bytes(v1001.SetActorDataPacket(**COMMON)) == bytes(v2168.SetActorDataPacket(**COMMON))
